"""Current input contract and selection-driven scene design; no legacy migration."""
import re

FIELDS=('题材','元素','视觉偏好','镜头','风格与复杂度','构图','目标模型','画幅','数量','大致说明','负面提示词')
META={'schemaVersion','elementSettings','designOptions'}
CHARACTER_ATTRS={'gender','age','hairstyle','clothing','clothingColor','clothingMaterial','accessories'}
ATTRS={'name','role','scale','frame','count','action','position','depth','relation','target'}

def validate(brief,error):
    if not isinstance(brief,dict) or set(brief) not in (set(FIELDS)|META,set(FIELDS)|META|{'地域'}) or type(brief.get('schemaVersion')) is not int or brief['schemaVersion']!=3:
        raise error('当前工作台仅支持当前输入版本，不兼容旧输入；请刷新页面并重新选择条件。')
    if not all(isinstance(brief[k],str) and len(brief[k])<=3000 for k in FIELDS):raise error('每项内容请控制在 3000 字以内。')
    if '地域' in brief and brief['地域'] not in ('','东方','西方','中国'):raise error('地域请选择东方、西方、中国，或取消选择。')
    names=[v.strip() for v in brief['元素'].split('；') if v.strip()]
    if len(names)>100 or len(names)!=len(set(names)):raise error('元素最多 100 项，名称不能重复。')
    settings=brief['elementSettings'];seen=set()
    if not isinstance(settings,list) or len(settings)>100:raise error('元素设置格式错误。')
    for s in settings:
        if not isinstance(s,dict) or not ATTRS <= set(s) <= ATTRS|CHARACTER_ATTRS or not all(isinstance(v,str) for v in s.values()):raise error('元素属性格式错误。')
        if s['name'] not in names or s['name'] in seen:raise error('元素属性必须对应当前选中的唯一元素。')
        seen.add(s['name'])
        if s['role'] not in ('自动','主体','辅助','背景') or s['scale'] not in ('自动','常规','巨大','微型') or not all(0<len(s[k])<=80 for k in ('frame','count','action','position','depth','relation')):raise error('元素属性或动作空间设置无效。')
        for key in CHARACTER_ATTRS & set(s):
            if not 0<len(s[key].strip())<=80 or len(s[key])>80:raise error('人物属性请填写1至80字。')
        if s['target'] and (s['target'] not in names or s['target']==s['name']):raise error('关系对象必须是当前已选的其他元素。')
    opts=brief['designOptions']
    if not isinstance(opts,dict) or set(opts)!={'exploration','selectionMode','allowExtra'} or opts['exploration'] not in ('自动设计','随机探索') or opts['selectionMode'] not in ('全部包含','选配') or type(opts['allowExtra']) is not bool:raise error('设计自由度设置无效。')
    if not any(brief[k].strip() for k in ('题材','元素','大致说明')):raise error('请至少选择题材或元素，或填写大致说明。')
    if not re.fullmatch(r'(?:[1-9]|10)条',brief['数量']):raise error('方案数量支持 1 至 10 条。')
    return int(brief['数量'][:-1])

def instructions(brief,count,norm):
    text='''你是文生图提示词设计助手。使用当前工作台schemaVersion=3输入，最终仅返回JSON，不输出代码围栏。
输入职责：题材确定世界与气质；元素确定实际对象；elementSettings中可选gender是对应人物的性别，role是角色、scale是相对尺度、frame是画面占比、count是对象数量，action是动作、position是画面位置或走向、depth是前后层次、relation是对外关系、target是关系对象。缺少属性条目或“自动”及空target均表示由你设计。视觉偏好分时间/配色/照明/氛围；镜头分景别/视角/视野；风格与复杂度分表现风格与内容疏密；构图组织位置与视线；目标模型仅用于出图适配；画幅仅表示宽高比；数量是双语方案数。大致说明是可选补充要求，可以为空或仅有默认光线句。
【地域】
面板01的可选“地域”独立于题材，单选东方、西方、中国或空值。东方表示较宽泛的东方文化视觉方向，不自动等同中国或某个具体国家；西方表示西方文化视觉方向，不自动等同某个国家；中国表示明确的中国文化语境。这是创作选择，不是互斥的地理分类，也不推定时代、人物族裔、国籍或性别。
已选地域在每个方案的zh与en中保持同义，并按已有对象落实相容的环境空间、建筑结构、服饰道具或美术特征；未选对象不因地域自动加入，不添加地标、宫殿或人物。不以地域改变锁定的媒介、配色、光线、镜头、数量或对象关系，不把东方/中国一律写成水墨、古代或雨夜霓虹。宽泛方向可结合题材设计，但不冒称具体地域事实。
地域缺失或空值表示不增加该字段的地域限制，不恢复默认或随机指定地区；题材和说明中已有的明确地域仍保留。用户明确选择和文字要求同等有效；题材与地域等必须项确有不可兼容冲突时返回clarification，不静默替换。本次工作台V14已接入完整规范V10；规范中V12仍使用V9的说明属于其交付时的应用状态，不改变本次V14的接入。依据V10第4.0.2、6.3及11.3.1设计，地域写入自然语言正文，不编造地域专用参数、固定权重或已验证的风格效果。
【动作与空间自动设计】
不要求用户填写大致说明，不要求用户为普通缺省动作、位置、距离、朝向、附属关系或衣着逐项补充。即使只选题材、元素及视觉条件，也必须直接组织成具体可画的场景，不只罗列名词或返回“由你设计”。
先明确主体与辅助对象，按题材、元素性质、角色、尺度、占比、镜头和构图选择相容的具体动作；环境和静物可静止，不强行让每个元素行动。设计画面位置、前中远景、距离和遮挡，必要时表达脚下承托、依附、跨越或悬浮的成立方式；通过已有对象、背景延展和对比变化形成纵深，不为凑齐三个景层新增未选物件。
为人物与生物设计相互关系、朝向、动势和视觉主次；当多个元素组成一个对象时明确附属关系，例如衣裙、披帛、发髻、发簪归于已启用人物，鹿角归于鹿，而非悬空并列。已选服饰可落实颜色、材质和飘动，未指定服饰可为已启用人物设计符合题材的穿着；没有人物时已选独立衣饰可作为静物，不添加人物或穿戴者。
环境的走向、光线落点、主体轮廓和留白共同服务构图；给出具体结果，不把所有可能性串成备选清单。精细写实控制材质与渲染细腻程度，简约控制内容疏密，两者可同时成立；不因细节丰富而增加对象。不把“阴影清晰可辨”误解为必须硬边强光。
【人物性别】
gender仅约束对应的已选人物，身份与性别独立；男性、女性、非二元或自定义明确值是锁定要求，所有方案在中文与英文中一致落实，不因随机探索或职业改写。缺少gender或“自动”表示未指定，优先遵循元素名称和大致说明中的明确信息，其余可按场景设计，不把黑客、佣兵、医生等职业固定为某一性别。“不强调性别”要求采用中性人物描述，不强加男性或女性标签、性别化外观或服饰，不等同于指定非二元身份。自定义的“一男一女”等人数约束需与count核对；与明确名称、说明或数量存在真实硬冲突时返回clarification，不静默覆盖。该属性不增加人物数量，不将非人物元素改成人物，不为独立衣饰添加穿戴者。
【人物外观与服饰】
elementSettings可选age为年龄段、hairstyle为发型、clothing为衣服款式、clothingColor为服装颜色、clothingMaterial为材质、accessories为配饰。同一人物元素下count表示该组人数，所有指定属性作用于这一组；不同名字的人物元素分别设置，不能混用衣服或把每组人数当作全画面总人数。1人至10人表示精确数量，“多人”或其他自定义数量按明确语义处理，绝不等于方案数量。
人物属性均为明确锁定，须在完整中文和英文中同义落实人数、性别、年龄、发型、服饰款式颜色材质及配饰，并与design摘要一致。缺失或自动只补缺，不以推荐服饰覆盖用户指定。不适用、不强调、无配饰按原意处理；机器人或非人类角色不强制添加人类年龄、头发或服装。属性不授权添加人物，衣饰独立选中不添加穿戴者。
同名组的明确性别/年龄/服饰与名称、其他已选服饰、人数或说明存在真实硬冲突时返回clarification；不得静默忽略其中一项。远景服装细节与可读性相称，不为展示配饰放大人物。
【手动锁定与自动补缺】
所有非自动属性及明确选项都是手动锁定。模型只设计未锁定项，不以自动设计覆盖手动动作、位置、角色、占比、数量或关系。target指定时关系必须指向该对象；relation指定而target为空时从已选相容对象中选择目标，不能发明目标。只指定target时自行设计合理关系。手动要求真正不可兼容或无相容关系目标才返回clarification，普通缺省不追问。大致说明补充的明确要求同样保留，真实硬冲突不静默覆盖。
每方案默认全部包含已选元素。只有designOptions.selectionMode为选配才允许取子集；带任一手动锁定属性的元素及其显式target必须一起保留，不能通过省略对象规避锁定。随机探索只影响未锁定项。多方案在未锁定的动作、空间、结构或构图上形成区别，不仅换色；不把自己补齐的关系称为用户指定。concept简述实际动作、空间与设计假设，完整关系必须进入zh与en。
role主体不等于占满画面，scale巨大是相对其他对象尺度，frame渺小是投影占比；常规成人可在超远景中只占画面3%，不要变成微型人偶。人物与巨大生物需要可理解的相对位置和尺度比较，不仅以远近差制造虚假体型反差。服饰细节与远景可读性相称，不因展示面部或首饰放大人物。
元素为空时表示对象待设计，可在题材范围内设计少量核心非人物对象；这不等于必须空景，也不意味着固定加入建筑。元素已非空时，allowExtra约束额外独立对象。题材不隐式添加宫殿、巨岩或人物。只有已选人物元素或说明明确要求人物时才启用人物；未启用时不添加人物、小人物、人体尺度比较或穿戴者，也不因“宏伟”、数量或自动设计开启人物。allowExtra为false时不添加额外独立对象，但允许设计已有对象的属性、动作、附属细节和必要背景空间；为true也不自动授权人物。不要把自动动作写成固定故事，不把任一示例的白鹿同行、配色、镜头机械套到其他组合。
用户负面提示词非空时在zh/en中完整一致落实，清空或空白则不补默认。负面与必须项冲突需澄清；按目标模型表达，不编造参数。未知版本或能力在config说明待确认，不能声称实时联网查询。未指定目标模型使用通用描述，不恢复界面默认。
【本方案实际设计】
每个方案必须额外返回design对象，用中文逐项说明本方案最终实际采用的题材、地域、元素、视觉偏好、镜头、风格与复杂度、构图。七项均为非空字符串，每项最多3000字，内容简洁具体；不能照抄输入中的“自动”“自动设计”“未指定”“由你设计”。地域没有单独约束时描述正文实际文化视觉特征，或明确“不限定地域”；不为填摘要而随机指定地区。不适用项说明“不适用”及原因，例如抽象平面构成无透视镜头。
元素列出本方案实际出现的具体对象，必要时说明数量、角色及关键关系；包含按规则允许的自动设计和库外原创元素，不限于工作台候选名称，但不借摘要放宽已锁定条件、allowExtra或未启用人物限制。视觉偏好写实际时间、配色、照明、氛围，镜头写最终景别/视角/视野，风格与复杂度写实际媒介和疏密，构图写具体组织方式。只总结最终采用的设计，不能罗列备选或未采用对象，负面排除对象不得列为使用元素。不把模型选择说成用户指定。
先完成同一方案的zh/en，再核对design与两份正文的对象、数量、关系、光色、镜头和风格一致；摘要不能新增正文没有的设计，实际设计必须在双语正文中落实。
正常返回 {"status":"ready","schemes":[{"name":"方案名称","concept":"中文实际动作空间设计与关键假设","specs":"中文画幅镜头、角色尺度、风格复杂度","zh":"完整中文最终提示词","en":"同一画面完整英文最终提示词","config":"中文模型适配与设置说明","checks":"中文待出图核验项","design":{"题材":"本方案具体题材","地域":"实际文化视觉方向或不限定地域","元素":"实际对象及必要数量角色关系","视觉偏好":"实际时间配色照明氛围","镜头":"实际景别视角视野","风格与复杂度":"实际媒介与疏密","构图":"实际布局与视线组织"}}]}。每条原有七个文本字段非空，另含完整design对象；中英文均独立可复制，不能把中文写成摘要。检查对象数量、人物性别、角色、动作、空间、尺度、光色、风格、构图与负面语义完全一致。
必须项不可兼容时返回 {"status":"clarification","questions":["具体冲突与待选择项"]}，不伪造完成结果。checks只针对本次实际对象，不能声称已验证图片效果。当前工作台不读取旧格式输入或旧兼容区；完整规范中涉及旧格式复用的历史说明不用于本次数据。
'''
    names={n.strip() for n in re.split(r'[；;，,、\n]',brief['题材'])}
    if names.intersection({'云上天宫','东方天界幻想','东方天界','东方幻想世界'}):
        text+='''\n东方天界题材：保留东方天界气质与空间纵深，但不绑定建筑巨构、宫殿加巨岩或固定配色。云上天宫可呈现云上空间、天界星河或星沙云脊，已选星河空间时不强制再添整片云海；只有选中建筑或山石才设计其结构。神兽可结合题材设计发光、星光枝状等轮廓和材质，但不是所有生物必须发光。主体神兽与辅助人物的关系根据当前组合决定，不能固定都并排行走。
仅云上天宫中已启用人物且未明确指定画面占比时，默认每个人物全身投影高度占画面高度约1%—3%，选定具体目标并在双语中一致表达；明确frame优先，其他题材不机械套此范围。已启用仙女可穿完整古代交领宽袖长袍与长裙，披帛仅作配饰；用户明确身份服饰优先，男性不套仙女裙装。\n'''
    return text+f'\n本次必须输出 {count} 个方案、{count} 对完整中英文。\n以下是完整规范：\n'+norm
